// 7-card poker hand evaluator.
//
// Two lookup tables built once at construction:
//   flush_table[rank_bits]  — 8192-entry uint16 array (perfect key across
//                             the 1287 flush classes; 5-bit-set patterns).
//   nonflush_table[hash]    — unordered_map from a 39-bit rank-count key
//                             (3 bits × 13 ranks) to the hand rank.
//
// Both tables are generated by enumerating every equivalence class,
// classifying and tiebreak-sorting it, then numbering the sorted list
// according to the Cactus Kev range offsets. This is slightly slower at
// init (~a few ms) than a static baked table, but bulletproof: no hand-
// rolled kicker arithmetic, no hash collisions, no precomputed blobs.

#include "hand_eval.h"

#include <algorithm>
#include <array>
#include <cstring>
#include <filesystem>
#include <fstream>
#include <functional>
#include <stdexcept>
#include <unordered_map>
#include <vector>

namespace pt {
namespace {

constexpr int FLUSH_TABLE_SIZE = 8192;  // 2^13 — every possible rank_bits mask

// Hot-path card encoding. Keep cheap fields aligned to nibble boundaries.
//   bits 28..16 : rank_bits (1 << rank)
//   bits 15..12 : suit_bits (1 << suit)
//   bits 11..8  : rank (0..12)
inline uint32_t encode_card(int rank, int suit) {
    return (1u << (rank + 16)) | (1u << (suit + 12)) |
           (static_cast<uint32_t>(rank) << 8);
}

inline bool all_same_suit(uint32_t c1, uint32_t c2, uint32_t c3,
                          uint32_t c4, uint32_t c5) {
    return ((c1 & c2 & c3 & c4 & c5) & 0xF000u) != 0;
}

constexpr uint32_t STRAIGHT_PATTERNS[10] = {
    0x1Fu << 8, 0x1Fu << 7, 0x1Fu << 6, 0x1Fu << 5, 0x1Fu << 4,
    0x1Fu << 3, 0x1Fu << 2, 0x1Fu << 1, 0x1Fu << 0, (1u << 12) | 0xFu,
};

// 0 = broadway (A-K-Q-J-T), 9 = wheel (5-4-3-2-A), -1 = not a straight.
inline int straight_index(uint32_t rank_bits) {
    for (int i = 0; i < 10; ++i)
        if ((rank_bits & STRAIGHT_PATTERNS[i]) == STRAIGHT_PATTERNS[i]) return i;
    return -1;
}

// ─── Non-flush rank table ───────────────────────────────────────────────────

inline uint64_t counts_key(const int* counts) {
    uint64_t k = 0;
    for (int i = 0; i < NUM_RANKS; ++i)
        k |= static_cast<uint64_t>(counts[i]) << (i * 3);
    return k;
}

constexpr int CAT_QUADS = 0;
constexpr int CAT_FH    = 1;
constexpr int CAT_STR   = 2;
constexpr int CAT_TRIPS = 3;
constexpr int CAT_2P    = 4;
constexpr int CAT_1P    = 5;
constexpr int CAT_HC    = 6;

// Cactus Kev rank ranges (inclusive).
constexpr uint16_t NONFLUSH_OFFSETS[7] = {
    11,    // quads     [11 .. 166]
    167,   // FH        [167 .. 322]
    1600,  // straight  [1600 .. 1609]
    1610,  // trips     [1610 .. 2467]
    2468,  // two pair  [2468 .. 3325]
    3326,  // one pair  [3326 .. 6185]
    6186,  // high card [6186 .. 7462]
};

struct Entry {
    std::array<int, NUM_RANKS> counts;
    int category;
    std::array<int, 5> tiebreak;  // descending by strength; unused slots = -1
};

Entry classify(const std::array<int, NUM_RANKS>& c) {
    int quads = -1, trips = -1;
    std::vector<int> pairs;    // descending
    std::vector<int> singles;  // descending
    for (int r = NUM_RANKS - 1; r >= 0; --r) {
        if (c[r] == 4)      quads = r;
        else if (c[r] == 3) trips = r;
        else if (c[r] == 2) pairs.push_back(r);
        else if (c[r] == 1) singles.push_back(r);
    }

    Entry e;
    e.counts = c;
    e.tiebreak.fill(-1);

    if (quads >= 0) {
        e.category = CAT_QUADS;
        e.tiebreak = {quads, singles[0], -1, -1, -1};
    } else if (trips >= 0 && !pairs.empty()) {
        e.category = CAT_FH;
        e.tiebreak = {trips, pairs[0], -1, -1, -1};
    } else if (trips >= 0) {
        e.category = CAT_TRIPS;
        e.tiebreak = {trips, singles[0], singles[1], -1, -1};
    } else if (pairs.size() >= 2) {
        e.category = CAT_2P;
        e.tiebreak = {pairs[0], pairs[1], singles[0], -1, -1};
    } else if (pairs.size() == 1) {
        e.category = CAT_1P;
        e.tiebreak = {pairs[0], singles[0], singles[1], singles[2], -1};
    } else {
        uint32_t rb = 0;
        for (int r = 0; r < NUM_RANKS; ++r) if (c[r] > 0) rb |= (1u << r);
        int si = straight_index(rb);
        if (si >= 0) {
            e.category = CAT_STR;
            // broadway (si=0) is strongest → 9; wheel (si=9) is weakest → 0
            e.tiebreak = {9 - si, -1, -1, -1, -1};
        } else {
            e.category = CAT_HC;
            e.tiebreak = {singles[0], singles[1], singles[2], singles[3], singles[4]};
        }
    }
    return e;
}

using NonFlushTable = std::unordered_map<uint64_t, uint16_t>;

NonFlushTable build_nonflush_table() {
    std::vector<Entry> entries;
    entries.reserve(6175);

    std::array<int, NUM_RANKS> counts{};
    std::function<void(int, int)> rec = [&](int r, int left) {
        if (r == NUM_RANKS) {
            if (left == 0) entries.push_back(classify(counts));
            return;
        }
        int lim = std::min(4, left);
        for (int x = 0; x <= lim; ++x) {
            counts[r] = x;
            rec(r + 1, left - x);
        }
        counts[r] = 0;
    };
    rec(0, 5);

    std::sort(entries.begin(), entries.end(),
              [](const Entry& a, const Entry& b) {
                  if (a.category != b.category) return a.category < b.category;
                  return a.tiebreak > b.tiebreak;  // higher = stronger
              });

    NonFlushTable T;
    T.reserve(entries.size() * 2);
    int counters[7] = {0};
    for (const auto& e : entries) {
        uint16_t rank = NONFLUSH_OFFSETS[e.category] +
                        static_cast<uint16_t>(counters[e.category]++);
        T[counts_key(e.counts.data())] = rank;
    }
    return T;
}

// ─── Flush table ────────────────────────────────────────────────────────────

struct FlushTable {
    alignas(32) std::array<uint16_t, FLUSH_TABLE_SIZE> t{};
};

FlushTable build_flush_table() {
    FlushTable F{};
    F.t.fill(7462);  // sentinel; unused slots never get queried

    struct FE { int tiebreak; uint32_t rank_bits; };
    std::vector<FE> sf, nf;
    sf.reserve(10);
    nf.reserve(1277);

    // C(13,5) = 1287 distinct rank-subsets.
    for (int a = 0; a < 13; ++a)
    for (int b = a + 1; b < 13; ++b)
    for (int c = b + 1; c < 13; ++c)
    for (int d = c + 1; d < 13; ++d)
    for (int e = d + 1; e < 13; ++e) {
        const uint32_t rb = (1u << a) | (1u << b) | (1u << c) | (1u << d) | (1u << e);
        int si = straight_index(rb);
        if (si >= 0)
            sf.push_back({9 - si, rb});            // SF: higher = stronger
        else
            nf.push_back({static_cast<int>(rb), rb});  // flush: higher rb = stronger
    }

    std::sort(sf.begin(), sf.end(),
              [](const FE& x, const FE& y) { return x.tiebreak > y.tiebreak; });
    std::sort(nf.begin(), nf.end(),
              [](const FE& x, const FE& y) { return x.tiebreak > y.tiebreak; });

    for (std::size_t i = 0; i < sf.size(); ++i)
        F.t[sf[i].rank_bits] = static_cast<uint16_t>(1 + i);       // [1..10]
    for (std::size_t i = 0; i < nf.size(); ++i)
        F.t[nf[i].rank_bits] = static_cast<uint16_t>(323 + i);     // [323..1599]
    return F;
}

}  // anonymous namespace

// ─── Impl ──────────────────────────────────────────────────────────────────

struct HandEvaluator::Impl {
    FlushTable flush;
    NonFlushTable nonflush;
    alignas(32) std::array<uint32_t, NUM_CARDS> deck{};

    Impl() {
        for (int rank = 0; rank < NUM_RANKS; ++rank)
            for (int suit = 0; suit < NUM_SUITS; ++suit)
                deck[make_card(rank, suit)] = encode_card(rank, suit);
        flush = build_flush_table();
        nonflush = build_nonflush_table();
    }

    uint16_t eval5_internal(uint32_t c1, uint32_t c2, uint32_t c3,
                            uint32_t c4, uint32_t c5) const {
        if (all_same_suit(c1, c2, c3, c4, c5)) {
            const uint32_t rb = ((c1 | c2 | c3 | c4 | c5) >> 16) & 0x1FFFu;
            return flush.t[rb];
        }
        int counts[NUM_RANKS] = {};
        counts[(c1 >> 8) & 0xF]++;
        counts[(c2 >> 8) & 0xF]++;
        counts[(c3 >> 8) & 0xF]++;
        counts[(c4 >> 8) & 0xF]++;
        counts[(c5 >> 8) & 0xF]++;
        return nonflush.at(counts_key(counts));
    }
};

// ─── Public API ────────────────────────────────────────────────────────────

HandEvaluator::HandEvaluator() : impl_(std::make_unique<Impl>()) {}
HandEvaluator::HandEvaluator(HandEvaluator&&) noexcept            = default;
HandEvaluator& HandEvaluator::operator=(HandEvaluator&&) noexcept = default;
HandEvaluator::~HandEvaluator()                                   = default;

HandEvaluator HandEvaluator::load_or_generate(std::string_view /*tables_path*/) {
    // Tables regenerate in a few ms and are correct by construction. Callers
    // can still pass a path for future caching, but we intentionally ignore it.
    return HandEvaluator{};
}

uint16_t HandEvaluator::evaluate5(const Card* cards) const {
    // Guard against unset cards (NO_CARD=0xFF). `deck` has NUM_CARDS=52 entries,
    // so deck[NO_CARD] would be an out-of-bounds read (UB). The Slumbot mirror
    // can reach a showdown before the board/holes are injected (cards still
    // NO_CARD); return the worst rank deterministically instead of reading OOB.
    // Training/solve paths always pass full hands, so this never fires there.
    for (int i = 0; i < 5; ++i)
        if (cards[i] >= NUM_CARDS) return 7462;   // worst rank (1=best..7462=worst)
    return impl_->eval5_internal(
        impl_->deck[cards[0]], impl_->deck[cards[1]], impl_->deck[cards[2]],
        impl_->deck[cards[3]], impl_->deck[cards[4]]);
}

uint16_t HandEvaluator::evaluate7(const Card* cards) const {
    // See evaluate5: an incomplete hand (any NO_CARD) ranks worst, no OOB read.
    uint32_t c[7];
    for (int i = 0; i < 7; ++i) {
        if (cards[i] >= NUM_CARDS) return 7462;
        c[i] = impl_->deck[cards[i]];
    }

    uint16_t best = 7462;
    #define E5(a,b,c_,d,e) best = std::min(best, impl_->eval5_internal(c[a],c[b],c[c_],c[d],c[e]))
    E5(0,1,2,3,4); E5(0,1,2,3,5); E5(0,1,2,3,6);
    E5(0,1,2,4,5); E5(0,1,2,4,6); E5(0,1,2,5,6);
    E5(0,1,3,4,5); E5(0,1,3,4,6); E5(0,1,3,5,6); E5(0,1,4,5,6);
    E5(0,2,3,4,5); E5(0,2,3,4,6); E5(0,2,3,5,6);
    E5(0,2,4,5,6); E5(0,3,4,5,6);
    E5(1,2,3,4,5); E5(1,2,3,4,6); E5(1,2,3,5,6);
    E5(1,2,4,5,6); E5(1,3,4,5,6);
    E5(2,3,4,5,6);
    #undef E5
    return best;
}

std::string_view HandEvaluator::rank_category(uint16_t r) {
    if (r <= 10)   return "Straight Flush";
    if (r <= 166)  return "Four of a Kind";
    if (r <= 322)  return "Full House";
    if (r <= 1599) return "Flush";
    if (r <= 1609) return "Straight";
    if (r <= 2467) return "Three of a Kind";
    if (r <= 3325) return "Two Pair";
    if (r <= 6185) return "One Pair";
    return "High Card";
}

}  // namespace pt
